import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"AI Platform Architecture","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"AI Platform Architecture | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/architecture/ai-platform"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"AI Platform Architecture | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/architecture/ai-platform"}]]},"headers":[],"relativePath":"architecture/ai-platform.md","filePath":"architecture/ai-platform.md","lastUpdated":1787339821000}'),i={name:"architecture/ai-platform.md"};function n(d,e,s,l,c,p){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="ai-platform-architecture" tabindex="-1">AI Platform Architecture <a class="header-anchor" href="#ai-platform-architecture" aria-label="Permalink to &quot;AI Platform Architecture&quot;">​</a></h1><p>Cross-cutting <strong>AI Assistant</strong> capability for EloSync workspaces. Product surface is licensed as the billable <code>ai</code> marketplace module; prepaid credit packs are additive SKUs that depend on <code>ai</code>.</p><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h2><ul><li>Answer business questions using <strong>trusted workspace context</strong> (modules, permissions, timezone).</li><li>Expose <strong>read-only tools</strong> gated by module entitlement and Spatie permissions.</li><li>Require <strong>explicit confirmation</strong> before low-risk writes (for example <code>create_task</code>).</li><li>Support <strong>Platform billing</strong> (Central provider + credit wallet) or <strong>BYOK</strong> (tenant-owned API key).</li></ul><h2 id="high-level-layout" tabindex="-1">High-level layout <a class="header-anchor" href="#high-level-layout" aria-label="Permalink to &quot;High-level layout&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tenant UI / API</span></span>
<span class="line"><span>    └── AIGateway (orchestration)</span></span>
<span class="line"><span>            ├── AiConfigResolver (platform | byok | central)</span></span>
<span class="line"><span>            ├── AiCreditWalletService (included + prepaid buckets)</span></span>
<span class="line"><span>            ├── AIToolRegistry + LaravelToolAdapter (permission-aware tools)</span></span>
<span class="line"><span>            ├── PendingAiActionService (write confirmation)</span></span>
<span class="line"><span>            ├── EloSyncBusinessAgent (laravel/ai structured output)</span></span>
<span class="line"><span>            ├── AiUsageRecorder + PlatformAuditService</span></span>
<span class="line"><span>            └── ContextBuilder (workspace + page context)</span></span></code></pre></div><h2 id="billing-modes" tabindex="-1">Billing modes <a class="header-anchor" href="#billing-modes" aria-label="Permalink to &quot;Billing modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Source</th><th>Credits</th></tr></thead><tbody><tr><td><strong>Platform</strong></td><td>Central <code>ai_api_key</code> when <code>ai_allow_platform</code></td><td>Burns wallet credits per token usage</td></tr><tr><td><strong>BYOK</strong></td><td>Tenant <code>ai_api_key</code> when <code>ai_mode=byok</code> and <code>ai_allow_byok</code></td><td>No platform credit burn</td></tr><tr><td><strong>Central</strong></td><td>Central key (operator/test flows)</td><td>N/A for tenant chat</td></tr></tbody></table><p>Workspace setting <code>ai_mode</code> defaults to <code>platform</code>. Tenant keys never appear in admin API payloads (masked as <code>********</code>).</p><h2 id="credit-wallet" tabindex="-1">Credit wallet <a class="header-anchor" href="#credit-wallet" aria-label="Permalink to &quot;Credit wallet&quot;">​</a></h2><p>Each workspace has one <code>ai_wallets</code> row:</p><ul><li><strong><code>included_remaining</code></strong> — monthly allowance from the AI module subscription; expires on rollover.</li><li><strong><code>prepaid_balance</code></strong> — purchased packs (<code>ai-credits-*</code> SKUs); carries over month to month.</li></ul><p>Ledger entries in <code>ai_credit_ledgers</code> record grants, burns, expirations, and purchase idempotency (reference = subscription).</p><p>Scheduled command: <code>ai:rollover-monthly-credits</code> (see <a href="/developer-guide/ai-credits">AI credits guide</a>).</p><h2 id="authorization-layers" tabindex="-1">Authorization layers <a class="header-anchor" href="#authorization-layers" aria-label="Permalink to &quot;Authorization layers&quot;">​</a></h2><ol><li><strong>Module gate</strong> — <code>module:ai</code> on tenant routes.</li><li><strong>Permissions</strong> — <code>ai.use</code>, <code>ai.confirm</code>, <code>ai.manage</code> (see <code>config/tenant-permissions.php</code>).</li><li><strong>Tool registry</strong> — each tool declares <code>module()</code> + <code>permissions()</code>; destructive tools are excluded.</li><li><strong>Policies</strong> — Lead Copilot endpoints call <code>Gate::authorize(&#39;view&#39;, $lead)</code>.</li><li><strong>Tenant isolation</strong> — <code>BelongsToTenant</code> global scope; foreign conversation IDs return 404.</li></ol><h2 id="data-model-tenant-db" tabindex="-1">Data model (tenant DB) <a class="header-anchor" href="#data-model-tenant-db" aria-label="Permalink to &quot;Data model (tenant DB)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Table</th><th>Purpose</th></tr></thead><tbody><tr><td><code>ai_conversations</code></td><td>User-owned chat threads</td></tr><tr><td><code>ai_messages</code></td><td>User/assistant turns + structured JSON</td></tr><tr><td><code>ai_pending_actions</code></td><td>Write proposals awaiting confirmation</td></tr><tr><td><code>ai_wallets</code></td><td>Dual-balance credit store</td></tr><tr><td><code>ai_credit_ledger</code></td><td>Immutable wallet movements</td></tr><tr><td><code>ai_usage_events</code></td><td>Token/credit telemetry</td></tr><tr><td><code>ai_tool_executions</code></td><td>Tool audit trail</td></tr></tbody></table><h2 id="lead-copilot" tabindex="-1">Lead Copilot <a class="header-anchor" href="#lead-copilot" aria-label="Permalink to &quot;Lead Copilot&quot;">​</a></h2><p>Focused endpoints on a single lead (<code>summarize</code>, <code>next-action</code>, <code>draft-follow-up</code>) reuse the gateway, wallet gate, and structured agent schema without tool calling.</p><h2 id="related-docs" tabindex="-1">Related docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related docs&quot;">​</a></h2><ul><li><a href="/developer-guide/ai-tools">AI tools — developer guide</a></li><li><a href="/developer-guide/ai-credits">AI credits — developer guide</a></li><li><a href="/api/tenant-v1-ai">Tenant AI API</a></li><li><a href="/user-guide/ai-assistant">AI Assistant — user guide</a></li><li><a href="/architecture/module-dependencies">Module dependencies — AI packs</a></li><li><a href="/deployment/ai">AI deployment</a> · <a href="/deployment/ai-production-readiness">Production readiness</a></li></ul>`,22)])])}const m=t(i,[["render",n]]);export{h as __pageData,m as default};
